// File contracts/lending/Garden.sol

pragma solidity 0.8.13;

// solhint-disable avoid-low-level-calls
// solhint-disable no-inline-assembly

/// @title Garden
/// @author BoringCrypto, Grandi
contract Garden is AccessControl, IMasterContract {
    using RebaseLibrary for Rebase;
    using BoringERC20 for IERC20;

    event LogExchangeRate(uint256 rate);
    event LogAccrue(uint128 accruedAmount);
    event LogAddCollateral(address indexed from, address indexed to, uint256 share);
    event LogRemoveCollateral(address indexed from, address indexed to, uint256 share);
    event LogBorrow(address indexed from, address indexed to, uint256 amount, uint256 part);
    event LogRepay(address indexed from, address indexed to, uint256 amount, uint256 part);
    event LogFeeTo(address indexed newFeeTo);
    event LogInterestPerSecond(uint64 interestPerSecond);
    event LogLiquidationMultiplier(uint256 liquidationMultiplier);
    event LogCollateralizationRate(uint256 collateralizationRate);
    event LogBorrowOpeningFee(uint256 borrowOpeningFee);
    event LogWithdrawFees(address indexed feeTo, uint256 feesEarnedFraction);
    event LogOracle(address oracle, bytes oracleData);

    // Immutables (for MasterContract and all clones)
    IBentoBoxV1 public immutable vase;
    Garden public immutable masterContract;
    IERC20 public immutable roseUsd;

    // MasterContract variables
    address public feeTo;

    // Per clone variables
    struct CloneInfo {
        // immutables
        address collateral;
        bool isBorrowWhitelisted;
        // changeable by the admin
        address oracle;
        bytes oracleData;
        uint256 collateralizationRate; // selector 3
        uint256 liquidationMultiplier; // selector 2
        uint256 borrowOpeningFee; // selector 1
        uint64 interestPerSecond; // selector 0
    }
    CloneInfo public cloneInfo;

    // Total amounts
    uint256 public totalCollateralShare; // Total collateral supplied
    Rebase public totalBorrow; // elastic = Total token amount to be repayed by borrowers, base = Total parts of the debt held by borrowers

    // User balances
    mapping(address => uint256) public userCollateralShare;
    mapping(address => uint256) public userBorrowPart;

    /// @notice Exchange and interest rate tracking.
    /// This is 'cached' here because calls to Oracles can be very expensive.
    uint256 public exchangeRate;

    struct AccrueInfo {
        uint64 lastAccrued;
        uint128 feesEarned;
    }
    AccrueInfo public accrueInfo;

    // constants
    uint256 private constant EXCHANGE_RATE_PRECISION = 1e18;
    uint256 private constant COLLATERIZATION_RATE_PRECISION = 1e5; // Must be less than EXCHANGE_RATE_PRECISION (due to optimization in math)
    uint256 private constant LIQUIDATION_MULTIPLIER_PRECISION = 1e5;
    uint256 private constant BORROW_OPENING_FEE_PRECISION = 1e5;
    uint256 private constant DISTRIBUTION_PART = 10;
    uint256 private constant DISTRIBUTION_PRECISION = 100;

    /// @notice Only allows the `admin` of the master garden to execute the function.
    modifier onlyAdmin() {
        require(masterContract.hasRole(DEFAULT_ADMIN_ROLE, msg.sender), "Garden: not an admin");
        _;
    }

    /// @notice Only allows an address from the `whitelist` to execute the function.
    modifier onlyWhitelisted() {
        if (cloneInfo.isBorrowWhitelisted) {
            bytes32 whitelistRole = keccak256(abi.encode(address(this), "_WHITELIST"));
            require(masterContract.hasRole(whitelistRole, msg.sender), "Garden: not whitelisted");
        }
        _;
    }

    /// @notice The constructor is only used for the initial master contract. Subsequent clones are initialised via `init`.
    constructor(IBentoBoxV1 vase_, IERC20 roseUsd_) {
        _setupRole(DEFAULT_ADMIN_ROLE, msg.sender);
        vase = vase_;
        roseUsd = roseUsd_;
        masterContract = this;
    }

    /// @notice Serves as the constructor for clones, as clones can't have a regular constructor
    /// @dev `data` is abi encoded
    function init(bytes calldata data) public payable override {
        require(address(cloneInfo.collateral) == address(0), "Garden: already initialized");
        (
            cloneInfo.collateral,
            cloneInfo.oracle,
            cloneInfo.isBorrowWhitelisted,
            cloneInfo.interestPerSecond,
            cloneInfo.liquidationMultiplier,
            cloneInfo.collateralizationRate,
            cloneInfo.borrowOpeningFee
        ) = abi.decode(data, (address, address, bool, uint64, uint256, uint256, uint256));
        require(address(cloneInfo.collateral) != address(0), "Garden: bad pair");
    }

    /// @notice Accrues the interest on the borrowed tokens and handles the accumulation of fees.
    function accrue() public {
        AccrueInfo memory _accrueInfo = accrueInfo;
        // Number of seconds since accrue was called
        // solhint-disable not-rely-on-time
        uint256 elapsedTime = block.timestamp - _accrueInfo.lastAccrued;
        if (elapsedTime == 0) {
            return;
        }
        _accrueInfo.lastAccrued = uint64(block.timestamp);
        // solhint-enable not-rely-on-time

        Rebase memory _totalBorrow = totalBorrow;
        if (_totalBorrow.base == 0) {
            accrueInfo = _accrueInfo;
            return;
        }

        // Accrue interest
        uint128 extraAmount = uint128((uint256(_totalBorrow.elastic) * cloneInfo.interestPerSecond * elapsedTime) / 1e18);
        _totalBorrow.elastic = _totalBorrow.elastic + extraAmount;

        _accrueInfo.feesEarned = _accrueInfo.feesEarned + extraAmount;
        totalBorrow = _totalBorrow;
        accrueInfo = _accrueInfo;

        emit LogAccrue(extraAmount);
    }

    /// @notice Concrete implementation of `isSolvent`. Includes a third parameter to allow caching `exchangeRate`.
    /// @param _exchangeRate The exchange rate. Used to cache the `exchangeRate` between calls.
    function _isSolvent(address user, uint256 _exchangeRate) internal view returns (bool) {
        // accrue must have already been called!
        uint256 borrowPart = userBorrowPart[user];
        if (borrowPart == 0) return true;
        uint256 collateralShare = userCollateralShare[user];
        if (collateralShare == 0) return false;

        Rebase memory _totalBorrow = totalBorrow;

        return
            vase.toAmount(
                cloneInfo.collateral,
                collateralShare * (EXCHANGE_RATE_PRECISION / COLLATERIZATION_RATE_PRECISION) * cloneInfo.collateralizationRate,
                false
            ) >=
            // Moved exchangeRate here instead of dividing the other side to preserve more precision
            (borrowPart * _totalBorrow.elastic * _exchangeRate) / _totalBorrow.base;
    }

    /// @dev Checks if the user is solvent in the closed liquidation case at the end of the function body.
    modifier solvent() {
        _;
        require(_isSolvent(msg.sender, exchangeRate), "Garden: user insolvent");
    }

    /// @notice Gets the exchange rate. I.e how much collateral to buy 1e18 asset.
    /// This function is supposed to be invoked if needed because Oracle queries can be expensive.
    /// @return updated True if `exchangeRate` was updated.
    /// @return rate The new exchange rate.
    function updateExchangeRate() public returns (bool updated, uint256 rate) {
        (updated, rate) = IOracle(cloneInfo.oracle).get(cloneInfo.oracleData);

        if (updated) {
            exchangeRate = rate;
            emit LogExchangeRate(rate);
        } else {
            // Return the old rate if fetching wasn't successful
            rate = exchangeRate;
        }
    }

    /// @dev Helper function to move tokens.
    /// @param token The ERC-20 token.
    /// @param share The amount in shares to add.
    /// @param total Grand total amount to deduct from this contract's balance. Only applicable if `skim` is True.
    /// Only used for accounting checks.
    /// @param skim If True, only does a balance check on this contract.
    /// False if tokens from msg.sender in `vase` should be transferred.
    function _addTokens(
        IERC20 token,
        uint256 share,
        uint256 total,
        bool skim
    ) internal {
        if (skim) {
            require(share <= vase.balanceOf(address(token), address(this)) - total, "Garden: Skim too much");
        } else {
            vase.transfer(address(token), msg.sender, address(this), share);
        }
    }

    /// @notice Adds `collateral` from msg.sender to the account `to`.
    /// @param to The receiver of the tokens.
    /// @param skim True if the amount should be skimmed from the deposit balance of msg.sender.x
    /// False if tokens from msg.sender in `vase` should be transferred.
    /// @param share The amount of shares to add for `to`.
    function addCollateral(
        address to,
        bool skim,
        uint256 share
    ) public {
        userCollateralShare[to] = userCollateralShare[to] + share;
        uint256 oldTotalCollateralShare = totalCollateralShare;
        totalCollateralShare = oldTotalCollateralShare + share;
        _addTokens(IERC20(cloneInfo.collateral), share, oldTotalCollateralShare, skim);
        emit LogAddCollateral(skim ? address(vase) : msg.sender, to, share);
    }

    /// @dev Concrete implementation of `removeCollateral`.
    function _removeCollateral(address to, uint256 share) internal {
        userCollateralShare[msg.sender] = userCollateralShare[msg.sender] - share;
        totalCollateralShare = totalCollateralShare - share;
        emit LogRemoveCollateral(msg.sender, to, share);
        vase.transfer(cloneInfo.collateral, address(this), to, share);
    }

    /// @notice Removes `share` amount of collateral and transfers it to `to`.
    /// @param to The receiver of the shares.
    /// @param share Amount of shares to remove.
    function removeCollateral(address to, uint256 share) public solvent {
        // accrue must be called because we check solvency
        accrue();
        _removeCollateral(to, share);
    }

    /// @dev Concrete implementation of `borrow`.
    /// @dev checks msg.sender against whitelist if garden was initialized with whitelist setting
    function _borrow(address to, uint256 amount) internal onlyWhitelisted returns (uint256 part, uint256 share) {
        uint256 feeAmount = (amount * cloneInfo.borrowOpeningFee) / BORROW_OPENING_FEE_PRECISION; // A flat % fee is charged for any borrow
        (totalBorrow, part) = totalBorrow.add(amount + feeAmount, true);
        accrueInfo.feesEarned = accrueInfo.feesEarned + uint128(feeAmount);
        userBorrowPart[msg.sender] = userBorrowPart[msg.sender] + part;

        // As long as there are tokens on this contract you can 'mint'... this enables limiting borrows
        share = vase.toShare(address(roseUsd), amount, false);
        vase.transfer(address(roseUsd), address(this), to, share);

        emit LogBorrow(msg.sender, to, (amount + feeAmount), part);
    }

    /// @notice Sender borrows `amount` and transfers it to `to`.
    /// @return part Total part of the debt held by borrowers.
    /// @return share Total amount in shares borrowed.
    function borrow(address to, uint256 amount) public solvent returns (uint256 part, uint256 share) {
        accrue();
        (part, share) = _borrow(to, amount);
    }

    /// @dev Concrete implementation of `repay`.
    function _repay(
        address to,
        bool skim,
        uint256 part
    ) internal returns (uint256 amount) {
        (totalBorrow, amount) = totalBorrow.sub(part, true);
        userBorrowPart[to] = userBorrowPart[to] - part;

        uint256 share = vase.toShare(address(roseUsd), amount, true);
        vase.transfer(address(roseUsd), skim ? address(vase) : msg.sender, address(this), share);
        emit LogRepay(skim ? address(vase) : msg.sender, to, amount, part);
    }

    /// @notice Repays a loan.
    /// @param to Address of the user this payment should go.
    /// @param skim True if the amount should be skimmed from the deposit balance of msg.sender.
    /// False if tokens from msg.sender in `vase` should be transferred.
    /// @param part The amount to repay. See `userBorrowPart`.
    /// @return amount The total amount repayed.
    function repay(
        address to,
        bool skim,
        uint256 part
    ) public returns (uint256 amount) {
        accrue();
        amount = _repay(to, skim, part);
    }

    // Functions that need accrue to be called
    uint8 internal constant ACTION_REPAY = 2;
    uint8 internal constant ACTION_REMOVE_COLLATERAL = 4;
    uint8 internal constant ACTION_BORROW = 5;
    uint8 internal constant ACTION_GET_REPAY_SHARE = 6;
    uint8 internal constant ACTION_GET_REPAY_PART = 7;
    uint8 internal constant ACTION_ACCRUE = 8;

    // Functions that don't need accrue to be called
    uint8 internal constant ACTION_ADD_COLLATERAL = 10;
    uint8 internal constant ACTION_UPDATE_EXCHANGE_RATE = 11;

    // Function on Vase
    uint8 internal constant ACTION_VASE_DEPOSIT = 20;
    uint8 internal constant ACTION_VASE_WITHDRAW = 21;
    uint8 internal constant ACTION_VASE_TRANSFER = 22;
    uint8 internal constant ACTION_VASE_TRANSFER_MULTIPLE = 23;
    uint8 internal constant ACTION_VASE_SETAPPROVAL = 24;

    // Any external call (except to Vase)
    uint8 internal constant ACTION_CALL = 30;

    int256 internal constant USE_VALUE1 = -1;
    int256 internal constant USE_VALUE2 = -2;

    /// @dev Helper function for choosing the correct value (`value1` or `value2`) depending on `inNum`.
    function _num(
        int256 inNum,
        uint256 value1,
        uint256 value2
    ) internal pure returns (uint256 outNum) {
        outNum = inNum >= 0 ? uint256(inNum) : (inNum == USE_VALUE1 ? value1 : value2);
    }

    /// @dev Helper function for depositing into `vase`.
    function _vaseDeposit(
        bytes memory data,
        uint256 value,
        uint256 value1,
        uint256 value2
    ) internal returns (uint256, uint256) {
        (IERC20 token, address to, int256 amount, int256 share) = abi.decode(data, (IERC20, address, int256, int256));
        amount = int256(_num(amount, value1, value2)); // Done this way to avoid stack too deep errors
        share = int256(_num(share, value1, value2));
        return vase.deposit{value: value}(address(token), msg.sender, to, uint256(amount), uint256(share));
    }

    /// @dev Helper function to withdraw from the `vase`.
    function _vaseWithdraw(
        bytes memory data,
        uint256 value1,
        uint256 value2
    ) internal returns (uint256, uint256) {
        (IERC20 token, address to, int256 amount, int256 share) = abi.decode(data, (IERC20, address, int256, int256));
        return vase.withdraw(address(token), msg.sender, to, _num(amount, value1, value2), _num(share, value1, value2));
    }

    /// @dev Helper function to perform a contract call and eventually extracting revert messages on failure.
    /// Calls to `vase` are not allowed for obvious security reasons.
    /// This also means that calls made from this contract shall *not* be trusted.
    function _call(
        uint256 value,
        bytes memory data,
        uint256 value1,
        uint256 value2
    ) internal returns (bytes memory, uint8) {
        (address callee, bytes memory callData, bool useValue1, bool useValue2, uint8 returnValues) = abi.decode(
            data,
            (address, bytes, bool, bool, uint8)
        );

        if (useValue1 && !useValue2) {
            callData = abi.encodePacked(callData, value1);
        } else if (!useValue1 && useValue2) {
            callData = abi.encodePacked(callData, value2);
        } else if (useValue1 && useValue2) {
            callData = abi.encodePacked(callData, value1, value2);
        }

        require(callee != address(vase) && callee != address(this), "Garden: can't call");

        (bool success, bytes memory returnData) = callee.call{value: value}(callData);
        require(success, "Garden: call failed");
        return (returnData, returnValues);
    }

    struct CookStatus {
        bool needsSolvencyCheck;
        bool hasAccrued;
    }

    /// @notice Executes a set of actions and allows composability (contract calls) to other contracts.
    /// @param actions An array with a sequence of actions to execute (see ACTION_ declarations).
    /// @param values A one-to-one mapped array to `actions`. ETH amounts to send along with the actions.
    /// Only applicable to `ACTION_CALL`, `ACTION_VASE_DEPOSIT`.
    /// @param datas A one-to-one mapped array to `actions`. Contains abi encoded data of function arguments.
    /// @return value1 May contain the first positioned return value of the last executed action (if applicable).
    /// @return value2 May contain the second positioned return value of the last executed action which returns 2 values (if applicable).
    function cook(
        uint8[] calldata actions,
        uint256[] calldata values,
        bytes[] calldata datas
    ) external payable returns (uint256 value1, uint256 value2) {
        CookStatus memory status;
        for (uint256 i = 0; i < actions.length; i++) {
            uint8 action = actions[i];
            if (!status.hasAccrued && action < 10) {
                accrue();
                status.hasAccrued = true;
            }
            if (action == ACTION_ADD_COLLATERAL) {
                (int256 share, address to, bool skim) = abi.decode(datas[i], (int256, address, bool));
                addCollateral(to, skim, _num(share, value1, value2));
            } else if (action == ACTION_REPAY) {
                (int256 part, address to, bool skim) = abi.decode(datas[i], (int256, address, bool));
                _repay(to, skim, _num(part, value1, value2));
            } else if (action == ACTION_REMOVE_COLLATERAL) {
                (int256 share, address to) = abi.decode(datas[i], (int256, address));
                _removeCollateral(to, _num(share, value1, value2));
                status.needsSolvencyCheck = true;
            } else if (action == ACTION_BORROW) {
                (int256 amount, address to) = abi.decode(datas[i], (int256, address));
                (value1, value2) = _borrow(to, _num(amount, value1, value2));
                status.needsSolvencyCheck = true;
            } else if (action == ACTION_UPDATE_EXCHANGE_RATE) {
                (bool mustUpdate, uint256 minRate, uint256 maxRate) = abi.decode(datas[i], (bool, uint256, uint256));
                (bool updated, uint256 rate) = updateExchangeRate();
                require((!mustUpdate || updated) && rate > minRate && (maxRate == 0 || rate > maxRate), "Garden: rate not ok");
            } else if (action == ACTION_VASE_SETAPPROVAL) {
                (address user, address _masterContract, bool approved, uint8 v, bytes32 r, bytes32 s) = abi.decode(
                    datas[i],
                    (address, address, bool, uint8, bytes32, bytes32)
                );
                vase.setMasterContractApproval(user, _masterContract, approved, v, r, s);
            } else if (action == ACTION_VASE_DEPOSIT) {
                (value1, value2) = _vaseDeposit(datas[i], values[i], value1, value2);
            } else if (action == ACTION_VASE_WITHDRAW) {
                (value1, value2) = _vaseWithdraw(datas[i], value1, value2);
            } else if (action == ACTION_VASE_TRANSFER) {
                (IERC20 token, address to, int256 share) = abi.decode(datas[i], (IERC20, address, int256));
                vase.transfer(address(token), msg.sender, to, _num(share, value1, value2));
            } else if (action == ACTION_VASE_TRANSFER_MULTIPLE) {
                (IERC20 token, address[] memory tos, uint256[] memory shares) = abi.decode(datas[i], (IERC20, address[], uint256[]));
                vase.transferMultiple(token, msg.sender, tos, shares);
            } else if (action == ACTION_CALL) {
                (bytes memory returnData, uint8 returnValues) = _call(values[i], datas[i], value1, value2);

                if (returnValues == 1) {
                    (value1) = abi.decode(returnData, (uint256));
                } else if (returnValues == 2) {
                    (value1, value2) = abi.decode(returnData, (uint256, uint256));
                }
            } else if (action == ACTION_GET_REPAY_SHARE) {
                int256 part = abi.decode(datas[i], (int256));
                value1 = vase.toShare(address(roseUsd), totalBorrow.toElastic(_num(part, value1, value2), true), true);
            } else if (action == ACTION_GET_REPAY_PART) {
                int256 amount = abi.decode(datas[i], (int256));
                value1 = totalBorrow.toBase(_num(amount, value1, value2), false);
            }
        }

        if (status.needsSolvencyCheck) {
            require(_isSolvent(msg.sender, exchangeRate), "Garden: user insolvent");
        }
    }

    /// @notice Handles the liquidation of users' balances, once the users' amount of collateral is too low.
    /// @param users An array of user addresses.
    /// @param maxBorrowParts A one-to-one mapping to `users`, contains maximum (partial) borrow amounts (to liquidate) of the respective user.
    /// @param to Address of the receiver in open liquidations if `swapper` is zero.
    function liquidate(
        address[] calldata users,
        uint256[] calldata maxBorrowParts,
        address to,
        address swapper
    ) public {
        // Oracle can fail but we still need to allow liquidations
        (, uint256 _exchangeRate) = updateExchangeRate();
        accrue();

        uint256 allCollateralShare;
        uint256 allBorrowAmount;
        uint256 allBorrowPart;
        Rebase memory _totalBorrow = totalBorrow;
        Rebase memory vaseTotals = vase.totals(cloneInfo.collateral);
        for (uint256 i = 0; i < users.length; i++) {
            address user = users[i];
            if (!_isSolvent(user, _exchangeRate)) {
                uint256 borrowPart;
                {
                    uint256 availableBorrowPart = userBorrowPart[user];
                    borrowPart = maxBorrowParts[i] > availableBorrowPart ? availableBorrowPart : maxBorrowParts[i];
                    userBorrowPart[user] = availableBorrowPart - borrowPart;
                }
                uint256 borrowAmount = _totalBorrow.toElastic(borrowPart, false);
                uint256 collateralShare = vaseTotals.toBase(
                    (borrowAmount * cloneInfo.liquidationMultiplier * _exchangeRate) /
                        (LIQUIDATION_MULTIPLIER_PRECISION * EXCHANGE_RATE_PRECISION),
                    false
                );

                userCollateralShare[user] = userCollateralShare[user] - collateralShare;
                emit LogRemoveCollateral(user, to, collateralShare);
                emit LogRepay(msg.sender, user, borrowAmount, borrowPart);

                // Keep totals
                allCollateralShare = allCollateralShare + collateralShare;
                allBorrowAmount = allBorrowAmount + borrowAmount;
                allBorrowPart = allBorrowPart + borrowPart;
            }
        }
        require(allBorrowAmount != 0, "Garden: all are solvent");
        _totalBorrow.elastic = uint128(_totalBorrow.elastic - allBorrowAmount);
        _totalBorrow.base = uint128(_totalBorrow.base - allBorrowPart);
        totalBorrow = _totalBorrow;
        totalCollateralShare = totalCollateralShare - allCollateralShare;

        // Apply a percentual fee share to protocol fee splitter
        {
            uint256 distributionAmount = ((allBorrowAmount * cloneInfo.liquidationMultiplier) / LIQUIDATION_MULTIPLIER_PRECISION) -
                ((allBorrowAmount) * (DISTRIBUTION_PART)) /
                DISTRIBUTION_PRECISION; // Distribution Amount
            allBorrowAmount = allBorrowAmount + distributionAmount;
            accrueInfo.feesEarned = accrueInfo.feesEarned + uint128(distributionAmount);
        }

        uint256 allBorrowShare = vase.toShare(address(roseUsd), allBorrowAmount, true);

        // Swap using a swapper freely chosen by the caller
        // Open (flash) liquidation: get proceeds first and provide the borrow after
        vase.transfer(cloneInfo.collateral, address(this), to, allCollateralShare);
        if (swapper != address(0)) {
            ISwapper(swapper).swap(IERC20(cloneInfo.collateral), roseUsd, msg.sender, allBorrowShare, allCollateralShare);
        }

        vase.transfer(address(roseUsd), msg.sender, address(this), allBorrowShare);
    }

    /// @notice Withdraws the fees accumulated.
    function withdrawFees() public {
        accrue();
        address _feeTo = masterContract.feeTo();
        uint256 _feesEarned = accrueInfo.feesEarned;
        accrueInfo.feesEarned = 0;
        uint256 share = vase.toShare(address(roseUsd), _feesEarned, false);
        vase.transfer(address(roseUsd), address(this), _feeTo, share);

        emit LogWithdrawFees(_feeTo, _feesEarned);
    }

    /// @notice reduces the supply of RUSD
    /// @param amount amount to reduce supply by
    function reduceSupply(uint256 amount) public onlyAdmin {
        vase.withdraw(address(roseUsd), address(this), address(this), amount, 0);
        IRoseUSD(address(roseUsd)).burn(amount);
    }

    /// @notice Sets the beneficiary of interest accrued.
    /// MasterContract Only Admin function.
    /// @param newFeeTo The address of the receiver.
    function setFeeTo(address newFeeTo) public onlyAdmin {
        feeTo = newFeeTo;
        emit LogFeeTo(newFeeTo);
    }

    function setGlobalParameter(uint256 param, int8 selector) public onlyAdmin {
        if (selector == 0) {
            cloneInfo.interestPerSecond = uint64(param);
            emit LogInterestPerSecond(uint64(param));
        } else if (selector == 1) {
            cloneInfo.borrowOpeningFee = param;
            emit LogBorrowOpeningFee(param);
        } else if (selector == 2) {
            cloneInfo.liquidationMultiplier = param;
            emit LogLiquidationMultiplier(param);
        } else if (selector == 3) {
            cloneInfo.collateralizationRate = param;
            emit LogCollateralizationRate(param);
        }
    }

    function setOracle(address newOracle, bytes calldata newOracleData) public onlyAdmin {
        cloneInfo.oracle = newOracle;
        cloneInfo.oracleData = newOracleData;
        emit LogOracle(newOracle, newOracleData);
    }
}
